const fields={particles:'입자',pinned:'고정',attachments:'강체 연결',generation:'초기화 세대'};
export function clothReadout(state={},kind='cloth'){return '<div class="cloth-readout" data-deformable-kind="'+kind+'">'+Object.entries(fields).map(([key,label])=>'<div class="component-property"><label>'+label+'</label><output data-'+kind+'-stat="'+key+'">'+(state[key]??0)+'</output></div>').join('')+'<div class="deformable-live-controls"><label>입자 <input type="number" data-deformable-index min="0" max="'+Math.max(0,(state.particles||1)-1)+'" step="1" value="0"></label><button data-deformable-control="pin">고정</button><button data-deformable-control="release">해제</button><button data-deformable-control="reset">초기화</button></div></div>';}
export function updateClothReadout(root,object,kind='cloth'){const s=object?.gameplayDebug?.[kind]||{},index=root.querySelector('[data-deformable-kind="'+kind+'"] [data-deformable-index]');if(index)index.max=String(Math.max(0,(s.particles||1)-1));for(const el of root.querySelectorAll('[data-'+kind+'-stat]')){const text=String(s[el.dataset[kind+'Stat']]??0);if(el.textContent!==text)el.textContent=text;}}
